#include <stdio.h>

int main(void) {
    int values[4] = {2, 4, 6, 8};
    int *first = values;
    printf("first=%d count=%zu\n", *first,
           sizeof values / sizeof values[0]);
    return 0;
}

#include <stdio.h>

void show_size(int values[], size_t count) {
    printf("parameter pointer size=%zu, count=%zu\n",
           sizeof values, count);
}

int main(void) {
    int data[5] = {0};
    show_size(data, sizeof data / sizeof data[0]);
    return 0;
}
